// Public outline of «Inglés para el día a día» (12 modules): titles, objectives and IDs only. Generated by
// scripts/vida-diaria-outline.mjs; the paid lessons are fetched from the server after access is verified.
import outline from './outline.json';
import type { LevelDefinition, Lesson, Unit } from '../../types';

export interface OutlineLesson { id: string; title: string; icon?: string; objective?: string; steps: number; practice: number }
export interface OutlineModule { id: string; unit: string; title: string; icon?: string; sample: boolean; lessons: OutlineLesson[] }

export const VIDA_DIARIA_PATH = 'vida-diaria/';
export const OUTLINE_MODULES = outline.modules as OutlineModule[];

/** Catalogue-only level (counts and syllabus): lessons carry no exercises. Never used to run a lesson. */
export const DAILY_OUTLINE_LEVEL: LevelDefinition = {
  id: 'DIA',
  track: 'daily',
  short: '🏙️ Día a día',
  name: 'Inglés para el día a día',
  description: 'Presentarte, comprar, moverte, trabajar, llamar, el colegio y la vida social, en una historia.',
  accent: '#C8102E',
  accentDark: '#950B22',
  accentLight: '#FBE3E7',
  instructionLanguage: 'es',
  units: OUTLINE_MODULES.map(
    (m): Unit => ({
      level: 'DIA',
      unit: m.unit,
      title: m.title,
      icon: m.icon,
      lessons: m.lessons.map((l): Lesson => ({ id: l.id, title: l.title, icon: l.icon, tip: l.objective, exercises: [] })),
    }) as Unit,
  ),
};
